"use client"

import type { ComponentProps } from "react"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./table.css"

type TableAlign = "start" | "center" | "end"

const alignClass: Record<TableAlign, string> = {
  start: "",
  center: "np-table-center",
  end: "np-table-end",
}

type TableProps = ComponentProps<"table"> & {
  containerClassName?: string
}

function Table({ className, containerClassName, ...props }: TableProps) {
  return (
    <div
      data-slot="table-container"
      className={cn("np-table-container", containerClassName)}
    >
      <table
        data-slot="table"
        className={cn("np-table", className)}
        {...props}
      />
    </div>
  )
}

function TableHeader({ className, ...props }: ComponentProps<"thead">) {
  return (
    <thead
      data-slot="table-header"
      className={cn("np-table-header", className)}
      {...props}
    />
  )
}

function TableBody({ className, ...props }: ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("np-table-body", className)}
      {...props}
    />
  )
}

function TableFooter({ className, ...props }: ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn("np-table-footer", className)}
      {...props}
    />
  )
}

function TableRow({ className, ...props }: ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn("np-table-row", className)}
      {...props}
    />
  )
}

type TableHeadProps = Omit<ComponentProps<"th">, "align"> & {
  align?: TableAlign
}

function TableHead({ className, align = "start", ...props }: TableHeadProps) {
  return (
    <th
      data-slot="table-head"
      data-align={align === "start" ? undefined : align}
      className={cn("np-table-head", alignClass[align], className)}
      {...props}
    />
  )
}

type TableCellProps = Omit<ComponentProps<"td">, "align"> & {
  align?: TableAlign
}

function TableCell({ className, align = "start", ...props }: TableCellProps) {
  return (
    <td
      data-slot="table-cell"
      data-align={align === "start" ? undefined : align}
      className={cn("np-table-cell", alignClass[align], className)}
      {...props}
    />
  )
}

function TableCaption({ className, ...props }: ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("np-table-caption", className)}
      {...props}
    />
  )
}

export {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
}
export type { TableAlign }

/* nepui — Table */

.np-table-container,
[data-np-table-container] {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  overflow-x: auto;
}

:is(.np-table-container, [data-np-table-container]):focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

.np-table,
[data-np-table] {
  --np-table-font-size: 0.875rem;
  --np-table-border-color: var(--np-border);
  --np-table-head-height: calc(var(--np-spacing) * 10);
  --np-table-head-color: var(--np-foreground);
  --np-table-cell-padding: calc(var(--np-spacing) * 2);
  --np-table-row-hover-bg: color-mix(
    in oklab,
    var(--np-muted) 50%,
    transparent
  );
  --np-table-row-selected-bg: var(--np-muted);
  --np-table-footer-bg: color-mix(in oklab, var(--np-muted) 50%, transparent);
  --np-table-caption-color: var(--np-muted-foreground);
  --np-table-caption-gap: calc(var(--np-spacing) * 4);

  box-sizing: border-box;
  width: 100%;
  caption-side: bottom;
  border-collapse: collapse;
  border-spacing: 0;
  text-indent: 0;
  font-size: var(--np-table-font-size);
}

:is(.np-table-header, [data-np-table-header]) > tr {
  border-bottom: 1px solid var(--np-table-border-color);
}

:is(.np-table-body, [data-np-table-body]) > tr:last-child {
  border-bottom: 0;
}

.np-table-footer,
[data-np-table-footer] {
  border-top: 1px solid var(--np-table-border-color);
  background-color: var(--np-table-footer-bg);
  font-weight: 500;
}

:is(.np-table-footer, [data-np-table-footer]) > tr:last-child {
  border-bottom: 0;
}

.np-table-row,
[data-np-table-row] {
  border-bottom: 1px solid var(--np-table-border-color);
  transition: background-color 150ms ease;
}

:is(.np-table-row, [data-np-table-row]):hover {
  background-color: var(--np-table-row-hover-bg);
}

:is(.np-table-row, [data-np-table-row]):is(
  [data-state="selected"],
  [data-selected],
  [aria-selected="true"]
) {
  background-color: var(--np-table-row-selected-bg);
}

.np-table-head,
[data-np-table-head] {
  box-sizing: border-box;
  height: var(--np-table-head-height);
  padding-inline: var(--np-table-cell-padding);
  color: var(--np-table-head-color);
  font-weight: 500;
  text-align: start;
  vertical-align: middle;
  white-space: nowrap;
}

.np-table-cell,
[data-np-table-cell] {
  box-sizing: border-box;
  padding: var(--np-table-cell-padding);
  text-align: start;
  vertical-align: middle;
  white-space: nowrap;
}

:is(
  .np-table-head,
  [data-np-table-head],
  .np-table-cell,
  [data-np-table-cell]
):has([role="checkbox"], input[type="checkbox"]) {
  padding-inline-end: 0;
}

.np-table-center,
:is(
  .np-table-head,
  [data-np-table-head],
  .np-table-cell,
  [data-np-table-cell]
)[data-align="center"] {
  text-align: center;
}

.np-table-end,
:is(
  .np-table-head,
  [data-np-table-head],
  .np-table-cell,
  [data-np-table-cell]
)[data-align="end"] {
  text-align: end;
}

.np-table-caption,
[data-np-table-caption] {
  box-sizing: border-box;
  margin-block-start: var(--np-table-caption-gap);
  color: var(--np-table-caption-color);
  font-size: var(--np-table-font-size);
}

@media (prefers-reduced-motion: reduce) {
  .np-table-row,
  [data-np-table-row] {
    transition: none;
  }
}
